import{_ as c,o as r,c as i,a2 as o,j as e,a as d,t as n}from"./chunks/framework.p9eYlHBT.js";const y=JSON.parse('{"title":"dsh ↔ FengAgentCli 服务契约映射（P2–P3）","description":"","frontmatter":{},"headers":[],"relativePath":"DSH-CONTRACT-MAP.md","filePath":"DSH-CONTRACT-MAP.md","lastUpdated":1794410944000}'),a={name:"DSH-CONTRACT-MAP.md"},l={tabindex:"0"};function p(s,t,h,g,u,k){return r(),i("div",null,[t[11]||(t[11]=o('<h1 id="dsh-↔-fengagentcli-服务契约映射-p2–p3" tabindex="-1">dsh ↔ FengAgentCli 服务契约映射（P2–P3） <a class="header-anchor" href="#dsh-↔-fengagentcli-服务契约映射-p2–p3" aria-label="Permalink to &quot;dsh ↔ FengAgentCli 服务契约映射（P2–P3）&quot;">​</a></h1><blockquote><p>适用版本：<code>@deepseek-ai/dsh-*@0.1.0-rc.6</code>（与本机 dsh CLI 同版）。 实现：<code>packages/dsh-compat/src/{projection,sessions,agents,agent-default-model,services-plugin}.ts</code>； 工具面：<code>{adapter,exec-context,events,plugin}.ts</code>。 本文与 <code>DSH_SERVICE_CAPABILITIES</code>（<code>src/services-plugin.ts</code>）必须同步修改—— 表里的每一行都能在代码里找到同名 <code>path</code>，反之亦然。</p></blockquote><h2 id="_0-一句话结论" tabindex="-1">0. 一句话结论 <a class="header-anchor" href="#_0-一句话结论" aria-label="Permalink to &quot;0. 一句话结论&quot;">​</a></h2><p>两边都是 Cordis 4.0.1 插件体系，<strong>插件形状天然互通</strong>；真正的差异在<strong>事实源</strong>：</p><table tabindex="0"><thead><tr><th></th><th>dsh</th><th>FengAgentCli</th></tr></thead><tbody><tr><td>会话事实源</td><td>append-only <code>SessionEvent[]</code>（事件溯源）</td><td><code>Message[]</code>（SQLite <code>sessions</code> / <code>messages</code>）</td></tr><tr><td>agent 创建</td><td>loop 实现 <code>AgentFactory</code>，registry 持有 live agent</td><td><code>ctx.loop.run(session)</code> 按会话跑回合，没有「创建即启动」的工厂面</td></tr><tr><td>作用域</td><td><code>ctx.agents.withInitiator</code> + <code>dsh-scope</code> 的 scope tag</td><td>无（P3 才做 scope）</td></tr></tbody></table><p>所以 P2 的映射原则是：<strong>能等价的直通（direct）、能投影的标注偏差（adapt）、 不能的明确抛错（unsupported）</strong>。绝不做「调用了但没生效」的静默降级。</p><h2 id="_1-能力分级" tabindex="-1">1. 能力分级 <a class="header-anchor" href="#_1-能力分级" aria-label="Permalink to &quot;1. 能力分级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>tier</th><th>含义</th><th>调用方应如何处理</th></tr></thead><tbody><tr><td><code>direct</code></td><td>与 dsh 语义等价，落库/身份无偏差</td><td>正常使用</td></tr><tr><td><code>adapt</code></td><td>可观察结果等价，但事件粒度/身份/持久化有<strong>已知且已文档化</strong>的偏差</td><td>可读；写入路径需确认偏差可接受</td></tr><tr><td><code>unsupported</code></td><td>无法在不伪造事实的前提下实现</td><td>装配前 preflight 拒绝，或捕获 <code>DshContractUnsupportedError</code></td></tr></tbody></table><p><code>unsupported</code> 一律抛 <code>DshContractUnsupportedError</code>，带 <code>code: &quot;dsh_contract_unsupported&quot;</code> 与 <code>contract</code> 路径；参数错误抛 <code>DshContractError</code>（<code>dsh_contract_invalid</code>）。</p><h2 id="_2-ctx-sessions" tabindex="-1">2. <code>ctx.sessions</code> <a class="header-anchor" href="#_2-ctx-sessions" aria-label="Permalink to &quot;2. `ctx.sessions`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dsh 成员</th><th>tier</th><th>FengAgentCli 侧</th><th>偏差/说明</th></tr></thead><tbody><tr><td><code>get(id)</code></td><td>direct</td><td><code>StorageService.loadSession</code></td><td>返回缓存的同一视图对象（身份稳定）</td></tr><tr><td><code>list()</code></td><td>adapt</td><td><code>StorageService.listSessions</code> + 逐条 <code>loadSession</code></td><td>列表元信息来自 <code>sessions</code> 表；每条都要读消息，N 条 = N 次查询</td></tr><tr><td><code>create(id?, {meta})</code></td><td>adapt</td><td><code>StorageService.saveSession</code></td><td>只支持空 <code>seed</code>；<code>meta.cwd</code> 校验绝对路径且只存在<strong>内存 header</strong>（sessions 表无此列）；<code>seedSource:&#39;persistence&#39;</code> 不支持</td></tr><tr><td><code>fork(src, boundary?, id?)</code></td><td>adapt</td><td><code>loadSession</code> + <code>saveMessages</code></td><td><strong>消息 id 必须重发</strong>：<code>messages.id</code> 是全局主键，沿用会 <code>INSERT OR REPLACE</code> 改写源会话的行；<code>boundary</code> 是投影后的 seq，经 <code>messageBoundaryForSeq</code> 换算成消息下标</td></tr><tr><td><code>flush(session)</code></td><td>direct</td><td><code>StorageService.flush</code></td><td>会话行是逐条同步写；这里刷的是图存储</td></tr><tr><td><code>prepare/enter/announce</code></td><td>unsupported</td><td>—</td><td>dsh 的「未发布创建事务」在 FengAgentCli 没有对应物；创建就是一次存储写</td></tr></tbody></table><h3 id="_2-1-session-投影面" tabindex="-1">2.1 <code>Session</code> 投影面 <a class="header-anchor" href="#_2-1-session-投影面" aria-label="Permalink to &quot;2.1 `Session` 投影面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>dsh 成员</th><th>tier</th><th>说明</th></tr></thead><tbody><tr><td><code>session.id</code></td><td>direct</td><td>会话 id</td></tr><tr><td><code>session.header</code></td><td>adapt</td><td><code>{version:1,id,createdAt}</code> + 内存 meta（cwd/parentSession/seedLength/origin/delegationDepth）</td></tr><tr><td><code>session.events</code></td><td>adapt</td><td>消息的<strong>有损投影</strong>，见 §4</td></tr><tr><td><code>session.append(type, data)</code></td><td>unsupported</td><td>写路径是 <code>saveMessage(s)</code>；伪造成事件会丢数据</td></tr><tr><td><code>session.requestHeader()</code></td><td>adapt</td><td>恒为 <code>undefined</code>——dsh 侧该返回值本身合法（没有 header 事件时）</td></tr><tr><td><code>session.surface</code></td><td>unsupported</td><td>投影不带 <code>surfaceOp</code> / <code>sourceEventSeqs</code>，推不出顺序 surface</td></tr></tbody></table><h2 id="_3-ctx-agents" tabindex="-1">3. <code>ctx.agents</code> <a class="header-anchor" href="#_3-ctx-agents" aria-label="Permalink to &quot;3. `ctx.agents`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dsh 成员</th><th>tier</th><th>说明</th></tr></thead><tbody><tr><td><code>get/list/roots</code></td><td>direct</td><td>进程内 registry；<code>roots</code> = <code>owner === undefined</code></td></tr><tr><td><code>register/enter/announce</code></td><td>direct</td><td><code>enter</code> 记录 owner 且 <code>announced=false</code>，<code>announce</code> 校验 exact entry（与 dsh 的重复发布检查一致）</td></tr><tr><td><code>isOwnedBy</code></td><td>direct</td><td>比较 owner 身份（不是会话血缘）</td></tr><tr><td><code>setFactory</code></td><td>direct</td><td>单槽位；重复注册抛错；disposer 清槽</td></tr><tr><td><code>create(options)</code></td><td>unsupported*</td><td><strong>未注册 factory 时抛错</strong>；注册了则原样委托 <code>factory.createAgent(ctx, options)</code></td></tr><tr><td><code>resume(options)</code></td><td>unsupported*</td><td>先校验目标会话存在，再委托 <code>factory.resume</code></td></tr><tr><td><code>withInitiator/withoutInitiator</code></td><td>direct</td><td><code>AsyncLocalStorage</code>：只做进程内因果归因，不做鉴权/liveness 证明</td></tr><tr><td><code>currentInitiator/requireInitiator</code></td><td>direct</td><td>无边界时 <code>current</code> 返回 <code>undefined</code>，<code>require</code> 抛 <code>DshContractError</code></td></tr></tbody></table><p>* <code>create/resume</code> 的分级取决于宿主是否注册了 factory。P2 交付<strong>不含</strong> loop → <code>AgentFactory</code> 的桥（属于 P4）：FengAgentCli 的 <code>ctx.loop</code> 需要先有 <code>Session</code> 才能 <code>run</code>，而 dsh 的 factory 契约是「创建会话 + agent + 启动 loop」的 组合事务。硬桥会造出一个「有 agent 但没有驱动」的假对象，所以选择显式缺失。</p><h2 id="_4-事件投影-为什么是-adapt-而不是-direct" tabindex="-1">4. 事件投影：为什么是 adapt 而不是 direct <a class="header-anchor" href="#_4-事件投影-为什么是-adapt-而不是-direct" aria-label="Permalink to &quot;4. 事件投影：为什么是 adapt 而不是 direct&quot;">​</a></h2><p><code>projectSessionEvents(messages)</code> 的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user 消息（text/thinking/image）      → user/message</span></span>\n<span class="line"><span>user 消息里的 tool-result 块（每个）  → tool/result</span></span>\n<span class="line"><span>assistant 消息（text/thinking/tool-use）→ assistant/message</span></span>\n<span class="line"><span>system 消息                            → 跳过（dsh 走 request/header）</span></span></code></pre></div><p>已知偏差（<strong>消费方必须知道</strong>）：</p><ol><li><strong>seq 不稳定</strong>：投影是派生视图，追加消息会让后续 seq 整体位移。dsh 的 seq 是 持久日志的稳定身份；任何把 seq 长期保存/跨进程比对的 dsh 插件在这里都不安全。</li><li><strong>没有 chunk / lifecycle</strong>：无 <code>assistant/chunk</code>、<code>turn/start|end</code>、<code>step/start|end</code>、 <code>request/header|context</code>、<code>session/end-seed</code>。<code>turn</code>/<code>step</code> 是合成值（每条 user 消息一轮、step=1），只满足读字段的形状，<strong>不可作为因果依据</strong>。</li><li><strong>没有 <code>surfaceOp</code></strong>：dsh 的 surface 是折叠产物；这里没有。</li><li><strong>image 块丢弃</strong>：dsh 用 attachment 引用，FengAgentCli 内联 base64，无等价物。</li><li><strong>消息 id 保留在事件里</strong>（<code>user/message</code>/<code>assistant/message</code> 的 <code>message.id</code> 即 <code>messages.id</code>），但 <code>fork</code> 之后子会话会重发 id（见 §2）。</li></ol><h3 id="_4-1-因此哪些-dsh-插件能装" tabindex="-1">4.1 因此哪些 dsh 插件能装 <a class="header-anchor" href="#_4-1-因此哪些-dsh-插件能装" aria-label="Permalink to &quot;4.1 因此哪些 dsh 插件能装&quot;">​</a></h3><table tabindex="0"><thead><tr><th>dsh 插件</th><th>inject</th><th>判定</th><th>原因</th></tr></thead><tbody><tr><td><code>dsh-llm-retry</code></td><td><code>agents</code></td><td>❌ 暂不可用</td><td>只用 <code>ctx.on(&#39;agent/request-error&#39;)</code>，事件由 dsh loop 发；FengAgentCli loop 不发该事件（P3 的 llm 面）</td></tr><tr><td><code>dsh-time-context</code></td><td><code>agents</code></td><td>❌ 暂不可用</td><td>依赖 <code>agent/pre-step</code> 扩展点与 <code>agent.session.events</code> 的 turn 语义</td></tr><tr><td><code>dsh-session-title</code></td><td><code>sessions</code></td><td>⚠️ 只读部分可用</td><td><code>get()</code> 能读投影；<code>rename/refresh</code> 走 <code>session.append(&#39;session/title&#39;)</code>，必抛</td></tr><tr><td><code>dsh-session-persistence-jsonl</code></td><td><code>sessions</code></td><td>❌ 不可用</td><td>监听 <code>session/event</code> / <code>session/flush</code> 并写事件日志——事实源冲突</td></tr><tr><td><code>dsh-session-query*</code> / <code>-telemetry-otel</code></td><td><code>sessions</code></td><td>❌ 不可用</td><td>读 <code>session.events</code> 的稳定 seq 与 surface</td></tr><tr><td><code>dsh-plugin-writing-guard</code></td><td><code>tools</code></td><td>✅ 工具 + 审计都可用</td><td>工具走 P1；<code>tools/pre-execute</code>/<code>post-execute</code> 审计经 §5.5 事件桥触发（宿主需把 <code>HookRegistry</code> 传给插件 <code>hooks</code>）；原生 <code>file-write</code>/<code>file-edit</code> 经名称映射（§5.5.2）也进自动审计</td></tr><tr><td><code>dsh-tool-todo-plus</code></td><td><code>tools</code> + <code>sessionProjections</code></td><td>❌ 仍不可用</td><td>① <code>sessionProjections</code> 不在 rc.6 契约（该插件面向 dsh 0.2.x）；② 工具写会话走 <code>exec.agent.session.append</code>，仍是 unsupported——但现在报 <code>dsh_contract_unsupported</code>，不再是 <code>TypeError</code></td></tr><tr><td><code>dsh-better-edit</code></td><td><code>tools</code> + <code>systemPrompt</code> + <code>fs</code></td><td>❌ 仍不可用</td><td>npm 包漏声明 <code>@deepseek-ai/dsh-fs</code> peer；<code>systemPrompt</code>/<code>fs</code> 服务面属 P3</td></tr><tr><td>tools-only 插件（P1）</td><td><code>tools</code></td><td>✅ 可用</td><td>见 <code>packages/dsh-compat/README.md</code></td></tr></tbody></table><p>结论：<strong>P2 让「服务面能解析、能读、能显式失败」成立，但还不能让事件溯源型 dsh 插件真正工作</strong>。真正的互操作要等 P3（llm/scope 扩展点）+ P4（FengAgentCli 插件进 dsh、群能力抽插件），届时事件桥才可能把 <code>session.append</code> 落到真实日志。</p><h2 id="_5-ctx-agentdefaultmodel" tabindex="-1">5. <code>ctx.agentDefaultModel</code> <a class="header-anchor" href="#_5-ctx-agentdefaultmodel" aria-label="Permalink to &quot;5. `ctx.agentDefaultModel`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dsh 成员</th><th>tier</th><th>说明</th></tr></thead><tbody><tr><td><code>currentSelection()</code></td><td>direct</td><td>读 <code>ctx.model.provider/model</code>；无模型服务时用构造期 fallback</td></tr><tr><td><code>saveSelection(next)</code></td><td>adapt</td><td>调 <code>ctx.model.switchProvider(provider, {model})</code> 热切换；dsh 还会写 settings 层，FengAgentCli 由配置文件/调用方负责；<code>reasoningEffort</code> 接受但忽略</td></tr></tbody></table><h2 id="_5-5-工具执行上下文与-dsh-事件桥-p2-第二批" tabindex="-1">5.5 工具执行上下文与 dsh 事件桥（P2 第二批） <a class="header-anchor" href="#_5-5-工具执行上下文与-dsh-事件桥-p2-第二批" aria-label="Permalink to &quot;5.5 工具执行上下文与 dsh 事件桥（P2 第二批）&quot;">​</a></h2><p>市场插件实测暴露的两个缺口在<strong>工具面</strong>补齐，不改服务面契约。</p><h3 id="_5-5-1-exec-上下文-src-exec-context-ts" tabindex="-1">5.5.1 <code>exec</code> 上下文（<code>src/exec-context.ts</code>） <a class="header-anchor" href="#_5-5-1-exec-上下文-src-exec-context-ts" aria-label="Permalink to &quot;5.5.1 `exec` 上下文（`src/exec-context.ts`）&quot;">​</a></h3><p>dsh 工具体签名是 <code>execute(args, exec)</code>；P1 只传了 <code>{ signal }</code>，于是读 <code>exec.agent</code> 的工具（todo-plus 一类）在 execute 阶段直接 <code>TypeError</code>。现在每次调用构造一份完整 <code>exec</code>：</p><table tabindex="0"><thead><tr><th>成员</th><th>来源</th><th>偏差</th></tr></thead><tbody><tr><td><code>callId</code> / <code>rootCallId</code></td><td><code>feng:&lt;messageId&gt;:&lt;tool&gt;:&lt;seq&gt;</code></td><td>进程内唯一；没有 dsh 的 transport 嵌套，故两者相等</td></tr><tr><td><code>token</code></td><td>每次调用一个新 symbol</td><td>不透明调用身份，<strong>不是</strong>鉴权 token</td></tr><tr><td><code>name</code> / <code>arguments</code></td><td>工具名 / 深冻结入参快照</td><td>与 dsh 的冻结语义对齐</td></tr><tr><td><code>signal</code></td><td><code>timeoutMs</code> 驱动的 AbortController</td><td>与 P1 一致</td></tr><tr><td><code>agent</code></td><td><code>ctx.agents.get(sessionId)</code> → 回落 <code>ctx.sessions.get(sessionId)</code> 的只读投影</td><td>没有 agent 时<strong>不伪造</strong>，保持 <code>undefined</code>（dsh 允许）</td></tr><tr><td><code>deferContext()</code> / <code>concludeTurn()</code></td><td>记录在 <code>exec.deferredContexts</code> / <code>exec.concludedTurn</code></td><td>FengAgentCli 的 <code>ToolResult</code> 没有 <code>additionalContexts</code> 通道、loop 没有「本回合结束」标记 → 仅记录 + 可选回调，<strong>不会自动生效</strong></td></tr></tbody></table><h3 id="_5-5-2-事件桥-src-events-ts" tabindex="-1">5.5.2 事件桥（<code>src/events.ts</code>） <a class="header-anchor" href="#_5-5-2-事件桥-src-events-ts" aria-label="Permalink to &quot;5.5.2 事件桥（`src/events.ts`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>dsh 事件 / 决策</th><th>FengAgentCli 侧</th><th>偏差</th></tr></thead><tbody><tr><td><code>tools/pre-execute</code> → <code>allow</code></td><td>继续执行</td><td>—</td></tr><tr><td><code>tools/pre-execute</code> → <code>deny</code></td><td><code>{allowed:false, reason}</code>（阻止执行）</td><td>—</td></tr><tr><td><code>tools/pre-execute</code> → <code>ask</code></td><td><strong>转 deny</strong></td><td>hook 阶段没有审批服务；放行会绕过审批 → fail-closed</td></tr><tr><td>监听器不调 <code>next()</code></td><td>视为 <code>deny</code></td><td>与 dsh waterfall 语义一致</td></tr><tr><td>监听器抛错</td><td>记警告 + 按 <code>allow</code> 继续</td><td>审计插件不能把工具执行带崩</td></tr><tr><td><code>tools/post-execute</code> → <code>accept</code> / <code>accept+content</code></td><td>保留结果 / 替换展示文本</td><td>只换文本，不动 canonical value</td></tr><tr><td><code>tools/post-execute</code> → <code>block</code></td><td>结果转 <code>isError</code> + feedback 文本</td><td>与 dsh「纠错反馈转错误结果」一致</td></tr><tr><td><code>tools/execute</code>（包裹执行）</td><td>不实现</td><td>超时已由适配器 <code>timeoutMs</code> 覆盖；重试/指标类插件需要 P3</td></tr><tr><td><code>tools/result</code> / <code>tools/change</code></td><td>不发</td><td>只读观察面，等 P3</td></tr></tbody></table><p>双向接线：</p><ul><li><strong>dsh 工具</strong>：适配器自己发 <code>pre → 工具体 → post</code>，三段共享<strong>同一份 exec</strong> （token/agent 一致），不经钩子路径；</li><li><strong>原生工具</strong>：宿主把 <code>HookRegistry</code> 传给 <code>dshCompatPlugin</code> 的 <code>hooks</code>（或注册成 <code>hooks</code> 服务），桥注册一对 pre/post 钩子，把原生工具的执行也翻译成 dsh 事件， 并把 dsh 侧决策映射回 <code>{allowed, reason}</code> / 错误结果；</li><li>适配器接管的工具名在钩子路径上被跳过（<code>markDshTool</code>），<strong>同一次调用不会发两遍</strong>；</li><li>原生工具的 <code>exec.signal</code> 是永不 abort 的信号（feng 执行器不把取消面暴露给 hook）。</li></ul><h4 id="名称映射-原生文件工具" tabindex="-1">名称映射（原生文件工具） <a class="header-anchor" href="#名称映射-原生文件工具" aria-label="Permalink to &quot;名称映射（原生文件工具）&quot;">​</a></h4><p>dsh 生态插件按 dsh 的工具名识别语义：<code>dsh-plugin-writing-guard</code> 的 <code>targetPathOf</code> 只认 <code>exec.name === &quot;write&quot; | &quot;edit&quot;</code>，而 FengAgentCli 原生工具叫 <code>file-write</code> / <code>file-edit</code>。桥在<strong>原生工具</strong>的钩子路径上按 <code>DEFAULT_NATIVE_TOOL_ALIASES</code> 映射名字，并把相对 <code>filePath</code> 按 hook 的 <code>workdir</code> 归一成绝对路径（writing-guard 直接 <code>fs.readFile(target)</code>，相对路径会按进程 cwd 解释，preimage 会读空、审计被静默跳过）：</p><table tabindex="0"><thead><tr><th>原生工具</th><th>事件里的 <code>exec.name</code></th><th><code>exec.arguments.filePath</code></th></tr></thead><tbody><tr><td><code>file-write</code></td><td><code>write</code></td><td>相对路径 → <code>resolve(workdir, filePath)</code></td></tr><tr><td><code>file-edit</code></td><td><code>edit</code></td><td>同上</td></tr><tr><td>其他原生工具</td><td>原名字</td><td>原样</td></tr></tbody></table><ul><li><code>callId</code> 里仍保留原生工具名（<code>feng-hook:&lt;messageId&gt;:file-write:&lt;seq&gt;</code>），便于回溯；</li><li>映射只影响事件面，FengAgentCli 内部注册/审批/展示仍用原生名；</li><li>需要覆盖或追加别名时给 <code>dshCompatPlugin</code> 传 <code>toolAliases</code>（在缺省映射之上合并）， 所以 <code>toolAliases: {}</code> 不会关掉缺省两条。</li></ul><h2 id="_6-装配与-preflight" tabindex="-1">6. 装配与 preflight <a class="header-anchor" href="#_6-装配与-preflight" aria-label="Permalink to &quot;6. 装配与 preflight&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createHookRegistry } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@fengagent/tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { dshCompatPlugin, applyDshServices } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@fengagent/dsh-compat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> hooks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createHookRegistry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 与 createToolExecutor 用同一个实例</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createRuntime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  workdir: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  plugins: [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;feng.storage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, config: { dbPath } },</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // P1 + P2 工具面：exec 上下文 + 事件桥（hooks 给了就双向接）</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { id: dshCompatPlugin, config: { hooks } },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { id: applyDshServices },               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// P2：sessions/agents/agentDefaultModel</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;some-dsh-plugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><blockquote><p><code>hooks</code> 也可不传：此时只有 dsh 工具自己发 <code>tools/*</code> 事件，原生工具的执行 不会出现在 dsh 事件里（审计插件只能看见 dsh 工具）。装配处顺手 <code>ctx.reflect.provide(&quot;hooks&quot;, hooks)</code> 也能被自动发现。</p></blockquote><p>preflight（宿主可放在插件加载器里）：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { DSH_SERVICE_CAPABILITIES, DshContractUnsupportedError } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@fengagent/dsh-compat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> blocked</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> DSH_SERVICE_CAPABILITIES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c.tier </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;unsupported&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 按插件实际调用的成员判断是否放行；不要在装配期假装全绿。</span></span></code></pre></div><h2 id="_7-ctx-llm-p3-src-llm-ts" tabindex="-1">7. <code>ctx.llm</code>（P3，<code>src/llm.ts</code>） <a class="header-anchor" href="#_7-ctx-llm-p3-src-llm-ts" aria-label="Permalink to &quot;7. `ctx.llm`（P3，`src/llm.ts`）&quot;">​</a></h2><p>dsh 的 <code>llm</code> 是「适配器注册表 + 可被 <code>llm/stream</code> 瀑布拦截的流式调用」；FengAgentCli 侧是 <code>ctx.model</code>（<code>@fengagent/llm</code> 的 <code>ModelService</code>，单条活跃路由 + <code>LLMEvent</code> 流）。 映射为 <strong>adapt</strong>：</p><table tabindex="0"><thead><tr><th>dsh 成员</th><th>FengAgentCli</th><th>分级</th><th>说明</th></tr></thead><tbody><tr><td><code>stream(options)</code></td><td>注册适配器直通 / 回落 <code>ModelService.stream</code></td><td>adapt</td><td>失败统一收敛为终态 `finish{kind:&#39;error&#39;</td></tr><tr><td><code>registerAdapter</code></td><td>路由表（独占 + disposer + <code>replace</code> 原子换路）</td><td>direct</td><td>与 dsh 的 all-or-nothing 语义一致</td></tr><tr><td><code>listProviders</code></td><td>当前模型路由 + 已注册路由</td><td>direct</td><td>适配器 <code>providerInfo</code> 生效</td></tr><tr><td><code>providerRetryPolicy</code></td><td>默认 normal 策略 / 适配器覆盖</td><td>adapt</td><td>只保存与回报；重试执行仍由 <code>dsh-llm-retry</code></td></tr><tr><td><code>listModels</code> / <code>resolveModelInfo</code></td><td>适配器委托；回落只报当前 model 身份</td><td>adapt</td><td>无 context/reasoning 元数据</td></tr><tr><td><code>prepareCall</code></td><td>config 冻结 + 单次派发</td><td>adapt</td><td><code>INVALID_PREPARED_CALL</code> 语义；不物化 adapterDefaults</td></tr><tr><td><code>registerConfigurableProviders</code> / <code>registerModelDiscovery</code></td><td>—</td><td>unsupported</td><td>需要 settings 命名空间与配置 UI 面</td></tr></tbody></table><p><strong>消息与内容块</strong>（<code>src/messages.ts</code>）：<code>text ↔ text</code>、<code>reasoning ↔ thinking</code>、 <code>tool-call(args 原始 JSON) ↔ tool-use(input 已解析)</code>、<code>tool-result(块数组) ↔ tool-result(文本)</code>； 消息 <strong>id 跨边界保留</strong>（dsh <code>MessageId</code> 稳定身份 = 我们的 <code>messages.id</code> 主键）。 图片块两个方向都没有等价物（dsh 是 attachment 引用、我们是 base64 inline），严格模式抛 <code>DshContractError</code>、宽松模式返回 loss 清单，不塞假文本。</p><p>已知偏差：</p><ul><li><code>GenerateOptions.tools</code> 是 JSON Schema，<code>ToolDefinition</code> 要 zod schema → 宿主必须注入 <code>LlmCompatOptions.toolSchemaConverter</code>；没注入时带 tools 的请求直接 以 <code>dsh_contract_unsupported</code> 终态失败（不静默丢工具让模型「看不见工具」）；</li><li><code>stop</code> 序列无对等字段（<code>LLMRequest</code> 不含 stop），接受但忽略；</li><li><code>reasoningEffort</code> 仅在注册适配器路径透传；回落路径忽略；</li><li><code>tool-result</code> 事件（loop 内部回填）在 dsh 流协议里没有对应 chunk，桥不发。</li></ul><p>装配：<code>dsh-services</code> 在 <code>ctx.model</code> 可用时 <code>provide(&quot;llm&quot;, LlmCompat)</code>；模型缺失时 <code>llm</code> 仍在位，调用期以 <code>NO_ADAPTER</code> 终态失败（装载期不炸）。</p><h2 id="_8-scope-p3-src-scope-ts" tabindex="-1">8. <code>scope</code>（P3，<code>src/scope.ts</code>） <a class="header-anchor" href="#_8-scope-p3-src-scope-ts" aria-label="Permalink to &quot;8. `scope`（P3，`src/scope.ts`）&quot;">​</a></h2><p><strong>结论：direct，零翻译。</strong> <code>scope</code> 不是 Cordis 服务——它是 <code>@deepseek-ai/dsh-scope</code> 的库级原语（<code>createScope</code> / <code>scopeOf</code> / <code>scopeTarget</code> / <code>bindScopeParent</code> / <code>ScopedLayers</code>）， 跑在同一条 Cordis 4 运行时上。兼容层<strong>直接重导出上游模块</strong>：</p><ul><li>保证与 dsh 插件内部 <code>import { scopeOf } from &quot;@deepseek-ai/dsh-scope&quot;</code> 是<strong>同一份模块 实例、同一套标签 symbol</strong>——自己再实现一份会让两边互相看不见标签，是最容易「假装 兼容、实际静默失效」的地方；</li><li>额外提供接线：<code>scopeKeyForSession(sessionId)</code>（进程内稳定同一把 key）、 <code>createAgentScope(ctx, { sessionId, parent })</code>、<code>scopeKeyOf</code> / <code>isScopedContext</code>。</li></ul><p>已验证（真 <code>createRuntime</code> 根上下文，非 stub）：标签随 <code>extend()</code> 继承、<code>dispose()</code> 幂等且真释放其下 effect、父子链顺序与循环拒绝、<code>scopeTarget</code> 的准入方向（祖先监听器 收后代事件，祖先事件不下发给后代）。</p><p><strong>留 P4</strong>：把 <code>tools/pre-execute</code> / <code>tools/post-execute</code> 发到 scope 载体上，让每个 agent 的审计插件只看到自己 agent 的事件（当前事件桥发全局事件，单 agent 场景等价，多 agent 并存时会串台）。</p><h2 id="_9-服务面清单-p3-采样-src-service-inventory-ts" tabindex="-1">9. 服务面清单（P3 采样，<code>src/service-inventory.ts</code>） <a class="header-anchor" href="#_9-服务面清单-p3-采样-src-service-inventory-ts" aria-label="Permalink to &quot;9. 服务面清单（P3 采样，`src/service-inventory.ts`）&quot;">​</a></h2><p>对 4 个 agent preset 去重出的 29 个插件包 + 25 个宿主/核心包 + 4 个市场插件逐包读 <code>inject</code> 后聚合（<code>DSH_SERVICE_INVENTORY</code>，可按分级做 preflight 诊断）：</p><table tabindex="0"><thead><tr><th>服务</th><th>必需</th><th>可选</th><th>软读</th><th>分级</th></tr></thead><tbody><tr><td><code>tools</code></td><td>23</td><td>0</td><td>1</td><td>mapped</td></tr><tr><td><code>systemPrompt</code></td><td>15</td><td>2</td><td>0</td><td>trivial-shim（下一批最高性价比）</td></tr><tr><td><code>sandboxPolicy</code></td><td>2</td><td>0</td><td>6</td><td>out-of-scope（宿主沙箱）</td></tr><tr><td><code>agents</code></td><td>4</td><td>1</td><td>2</td><td>mapped</td></tr><tr><td><code>fs</code></td><td>3</td><td>0</td><td>3</td><td>trivial-shim</td></tr><tr><td><code>sessionProjections</code></td><td>1</td><td>5</td><td>0</td><td>needs-design（todo-plus 硬门槛）</td></tr><tr><td><code>sessions</code></td><td>2</td><td>0</td><td>2</td><td>mapped</td></tr><tr><td><code>subagents</code></td><td>4</td><td>0</td><td>0</td><td>needs-design</td></tr><tr><td><code>jobs</code> / <code>skills</code> / <code>tokenMeter</code> / <code>workflowEngine</code> / <code>terminals</code></td><td>1–2</td><td>0</td><td>0–3</td><td>needs-design</td></tr><tr><td><code>llm</code></td><td>1</td><td>0</td><td>1</td><td><strong>p3（本轮）</strong></td></tr><tr><td><code>commands</code> / <code>settings</code> / <code>attachments</code></td><td>0–1</td><td>0–1</td><td>0–2</td><td>trivial-shim</td></tr><tr><td><code>shell</code> / <code>shellEnv</code> / <code>subprocess</code> / <code>web</code> / <code>approval</code> / <code>userQuestions</code> / <code>typert</code></td><td>0–2</td><td>0</td><td>0–7</td><td>out-of-scope（宿主面）</td></tr></tbody></table><p>排期建议：<code>systemPrompt → fs → settings → skills → sessionProjections → llm 的消费者</code> （<code>llm</code> 唯一硬依赖 <code>compaction-basic</code> 同时要 <code>tokenMeter</code>+<code>sessions</code>，先把投影面补上更划算）。</p><p>采样注意：npm 的 <code>latest</code> tag 对多数 <code>@deepseek-ai/dsh-*</code> 陈旧（停在 0.0.1-rc.1）， preset 实际用 0.1.0-rc.8——不 pin 版本会读到错误的 inject 结构。</p><p>市场插件现状：<code>writing-guard</code> / <code>notes</code> 只需 <code>tools</code>（现成可跑）；<code>todo-plus</code> 硬要 <code>sessionProjections</code>、<code>better-edit</code> 要 <code>systemPrompt</code>+<code>fs</code>——三面已在 P3 收尾补齐， 分级从 <code>trivial-shim</code> / <code>needs-design</code> 翻成 <code>mapped</code>，偏差与口径见 §10。</p><h2 id="_10-systemprompt-fs-sessionprojections-p3-收尾" tabindex="-1">10. <code>systemPrompt</code> / <code>fs</code> / <code>sessionProjections</code>（P3 收尾） <a class="header-anchor" href="#_10-systemprompt-fs-sessionprojections-p3-收尾" aria-label="Permalink to &quot;10. `systemPrompt` / `fs` / `sessionProjections`（P3 收尾）&quot;">​</a></h2><p>三个服务面补在 <code>dsh-services</code> 里，与前面几节的装配口径一致 （<code>ctx.reflect.provide</code>，随 fiber 卸载自动注销）。</p><h3 id="_10-1-ctx-systemprompt-src-system-prompt-ts" tabindex="-1">10.1 <code>ctx.systemPrompt</code>（<code>src/system-prompt.ts</code>） <a class="header-anchor" href="#_10-1-ctx-systemprompt-src-system-prompt-ts" aria-label="Permalink to &quot;10.1 `ctx.systemPrompt`（`src/system-prompt.ts`）&quot;">​</a></h3><p>按 <code>@deepseek-ai/dsh-system-prompt@0.2.1</code> 的面实现注册 + 装配：</p>',66)),e("table",l,[t[10]||(t[10]=e("thead",null,[e("tr",null,[e("th",null,"成员"),e("th",null,"实现"),e("th",null,"分级")])],-1)),e("tbody",null,[t[5]||(t[5]=e("tr",null,[e("td",null,[e("code",null,"section(spec)"),d(" / "),e("code",null,"context(spec)")]),e("td",null,[d("有序注册表 + disposer；"),e("code",null,"order"),d(" 升序、同序按 name 的 code-unit")]),e("td",null,"adapt")],-1)),t[6]||(t[6]=e("tr",null,[e("td",null,[e("code",null,"getSectionOrder"),d(" / "),e("code",null,"getContextOrder")]),e("td",null,"中心槽位表（与上游逐项一致），未知名字抛错"),e("td",null,"direct")],-1)),e("tr",null,[t[3]||(t[3]=e("td",null,[e("code",null,"variable(name, fn)")],-1)),e("td",null,[t[0]||(t[0]=e("code",null,"[a-z][a-z0-9_]*",-1)),t[1]||(t[1]=d(" 校验；",-1)),e("code",null,n(s.name),1),t[2]||(t[2]=d(" 严格插值",-1))]),t[4]||(t[4]=e("td",null,"direct",-1))]),t[7]||(t[7]=e("tr",null,[e("td",null,[e("code",null,"tools(provider)")]),e("td",null,"每次装配求值，schema 原样透传"),e("td",null,"adapt")],-1)),t[8]||(t[8]=e("tr",null,[e("td",null,[e("code",null,"suppressRuntimeContext()")]),e("td",null,[d("引用计数压制可选上下文（"),e("code",null,"required"),d(" 保留）")]),e("td",null,"direct")],-1)),t[9]||(t[9]=e("tr",null,[e("td",null,[e("code",null,"assemble()"),d(" / "),e("code",null,"refreshContext()")]),e("td",null,[d("段落/上下文/变量快照；"),e("code",null,"renderPrompt"),d(" 空段落丢弃、空行分隔")]),e("td",null,"adapt")],-1))])]),t[12]||(t[12]=o('<p>偏差：</p><ol><li><strong>不按 scope 分层</strong>：<code>ctx.reflect.provide</code> 只挂一个实例，拿不到「调用者所在 scope」。所有注册落在同一层，同名按<strong>引用计数覆盖</strong>——后注册者赢，最后一个 disposer 才移除。多 agent 同时装 <code>better-edit</code> 不会互相抛「重复段落」， 代价是「每 agent 各一份文案」退化成「最后安装者一份」。</li><li><strong><code>complete</code> 段落</strong>取最后一个（上游多于一个即装配失败），避免把宿主整个提示 词打挂。</li><li>段落函数形式（<code>text: (ctx) =&gt; string</code>）每次装配求值一次，与上游一致。</li></ol><h3 id="_10-2-ctx-fs-src-fs-ts" tabindex="-1">10.2 <code>ctx.fs</code>（<code>src/fs.ts</code>） <a class="header-anchor" href="#_10-2-ctx-fs-src-fs-ts" aria-label="Permalink to &quot;10.2 `ctx.fs`（`src/fs.ts`）&quot;">​</a></h3><p>本机后端，语义按 <code>dsh-fs@0.1.0-rc.6</code> 写并补了 0.2.x 的 <code>readByteRange</code>： <code>resolve</code> / <code>processPath</code> / <code>fileUrl</code> / <code>contains</code> / <code>stat</code> / <code>lstat</code> / <code>readText</code> / <code>streamText</code> / <code>readBytes</code> / <code>readByteRange</code> / <code>listDir</code> / <code>writeText</code> / <code>editText</code>。</p><ul><li>错误统一带 <code>code</code>（<code>FS_NOT_FOUND</code> / <code>FS_NOT_TEXT</code> / <code>FS_NOT_REGULAR_FILE</code> / <code>FS_TOO_LARGE</code> / <code>FS_STALE_VERSION</code> / <code>FS_NOT_OBSERVED</code> / <code>FS_AMBIGUOUS_EDIT</code> / <code>FS_EDIT_NOT_FOUND</code> / <code>FS_ABORTED</code>），工具层按 code 分支；</li><li><code>writeText</code> 是<strong>同目录 tmp + rename</strong> 的原子写，<code>createIfAbsent</code> / <code>replaceIfVersion</code> 两个守卫按契约抛错；</li><li>偏差：<strong>不装沙箱</strong>（<code>sandboxMode</code> 恒 <code>undefined</code>，<code>sandboxPolicy</code> 接受但忽略）； <code>version</code> 是 <code>size:mtimeMs</code> 的派生串而不是 inode 身份；<code>editText</code> 只做字面量 替换，不做行尾归一化。</li></ul><h3 id="_10-3-ctx-sessionprojections-进程内事件日志-src-session-projections-ts-src-session-events-ts" tabindex="-1">10.3 <code>ctx.sessionProjections</code> + 进程内事件日志（<code>src/session-projections.ts</code> / <code>src/session-events.ts</code>） <a class="header-anchor" href="#_10-3-ctx-sessionprojections-进程内事件日志-src-session-projections-ts-src-session-events-ts" aria-label="Permalink to &quot;10.3 `ctx.sessionProjections` + 进程内事件日志（`src/session-projections.ts` / `src/session-events.ts`）&quot;">​</a></h3><p><code>register</code> / <code>onChanged</code> / <code>stateOf</code> / <code>snapshot</code> / <code>cachedSnapshot</code> / <code>checkpoint</code> / <code>restoreFloor</code> / <code>viewCheckpoint</code> / <code>restore</code> / <code>hydrate</code> 全部按上游形状实现， 驱动由宿主接线：<code>SessionsCompat.append()</code> 写 <code>SessionEventLog</code> 后调 <code>drive()</code>。</p><ul><li><code>register</code> 同名按引用计数（多 preset 装同一插件），disposer 归零即摘单元与缓存；</li><li>折叠规则与上游一致：<code>apply</code> 返回<strong>同一引用</strong>视为「不关心」，<code>wire</code> 视图按 <code>Object.is</code> 推送变更；<code>apply</code>/<code>view</code>/监听器抛错都只记警告，不把会话写路径带崩；</li><li><code>checkpoint()</code> 的 <code>val</code> 是 detached 克隆，<code>restore()</code> 在没有可用检查点且 <code>baseSeq &gt; 0</code> 时按上游口径要求「从头折」；</li><li><strong>偏差</strong>：事件日志只在<strong>进程内</strong>（不落盘），所以 <code>restoreFloor()</code> 恒为 <code>0</code>、 重启后领域事件丢失；<code>CompatSession.events</code> 是「消息投影 + 领域事件」的拼接视图， 领域事件的 <code>seq</code> 会随消息增长整体后移，<strong>不能当稳定游标</strong>（消息仍是 SQLite 里 的唯一持久事实源）。跨重启的事件溯源持久化仍属 P4。</li></ul><p>市场插件口径因此更新（见 <code>service-inventory.ts</code>）：</p><table tabindex="0"><thead><tr><th>插件</th><th>inject</th><th>现在</th></tr></thead><tbody><tr><td><code>dsh-better-edit@1.2.0</code></td><td><code>tools</code> + <code>systemPrompt</code> + <code>fs</code></td><td>三个服务齐全，挂载门槛放行（Bun 侧仍需处理它自己依赖的 <code>node:sqlite</code>）</td></tr><tr><td><code>dsh-tool-todo-plus@0.7.4</code></td><td><code>tools</code> + <code>sessionProjections</code></td><td>预检通过、工具注册、<code>todo/write</code> 进投影；面板值随 append 实时更新</td></tr></tbody></table><h2 id="_11-升级-dsh-版本时的复核清单" tabindex="-1">11. 升级 dsh 版本时的复核清单 <a class="header-anchor" href="#_11-升级-dsh-版本时的复核清单" aria-label="Permalink to &quot;11. 升级 dsh 版本时的复核清单&quot;">​</a></h2><ol><li><code>dsh-session</code> 的 <code>SessionStore</code> 方法集合是否变化（本文件 §2 表）；</li><li><code>dsh-agent</code> 的 <code>AgentRegistry</code> 方法集合是否变化（§3 表）；</li><li><code>SessionEventMap</code> 的 surface 事件类型是否仍是 <code>user/message | assistant/message | tool/result</code>（§4）；</li><li><code>dsh-agent-default-model</code> 的 <code>ModelSelection</code> 是否新增必填字段（§5）；</li><li><code>dsh-tools</code> 的 <code>ToolRunContext</code> / <code>PreToolDecision</code> / <code>PostToolDecision</code> 是否变化（§5.5）；</li><li><code>dsh-llm</code> 的 <code>StreamChunk</code> / <code>GenerateOptions</code> / <code>LlmRuntime</code> 方法集合是否变化（§7）；</li><li><code>dsh-scope</code> 的导出集与 <code>Context.filter</code> 口径是否变化（§8）；根级 peer 矩阵里 <code>dsh-scope</code> 与 <code>dsh-llm</code> 是否同版本；</li><li><code>dsh-system-prompt</code> 的 <code>SECTION_ORDERS</code> / <code>CONTEXT_ORDERS</code> 槽位值与 <code>SystemPrompt</code> 方法集合是否变化（§10.1）；<code>dsh-fs</code> 的 <code>FileSystem</code> 抽象方法 是否新增（§10.2）；<code>dsh-session-projection</code> 的 <code>ProjectionDefinition</code> 是否新增 必填字段（§10.3）；</li><li>重跑服务面采样（<code>DSH_SERVICE_INVENTORY</code>），确认 <code>inject</code> 分级没有被新版翻转；</li><li>跑 <code>bun test packages/dsh-compat</code>，再跑全量 <code>bun test</code>。</li></ol>',12))])}const E=c(a,[["render",p]]);export{y as __pageData,E as default};
